#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <limits.h>

typedef struct {
    int x1, y1, x2, y2;
} Rect;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}

static int coord_index(const int *a, int n, int x) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

static void range_add(int32_t *diff, int stride,
                      int r1, int c1, int r2, int c2) {
    diff[(size_t)r1 * stride + c1]++;
    diff[(size_t)r2 * stride + c1]--;
    diff[(size_t)r1 * stride + c2]--;
    diff[(size_t)r2 * stride + c2]++;
}

static void build_coverage(int32_t *diff, int rows, int cols) {
    int stride = cols + 1;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            size_t p = (size_t)r * stride + c;
            int32_t v = diff[p];
            if (r) v += diff[p - stride];
            if (c) v += diff[p - 1];
            if (r && c) v -= diff[p - stride - 1];
            diff[p] = v;
        }
    }
}

static int less_vertex(int a, int b, const int *dist) {
    return dist[a] < dist[b];
}

static void heap_up(int *heap, int *pos, int size, int v, const int *dist) {
    int i = pos[v];
    while (i > 0) {
        int p = (i - 1) / 2;
        if (!less_vertex(v, heap[p], dist)) break;
        heap[i] = heap[p];
        pos[heap[i]] = i;
        i = p;
    }
    heap[i] = v;
    pos[v] = i;
}

static int heap_pop(int *heap, int *pos, int *size, const int *dist) {
    int result = heap[0];
    pos[result] = -2;
    int last = heap[--(*size)];
    if (*size == 0) return result;

    int i = 0;
    while (2 * i + 1 < *size) {
        int child = 2 * i + 1;
        if (child + 1 < *size && less_vertex(heap[child + 1], heap[child], dist))
            child++;
        if (!less_vertex(heap[child], last, dist)) break;
        heap[i] = heap[child];
        pos[heap[i]] = i;
        i = child;
    }
    heap[i] = last;
    pos[last] = i;
    return result;
}

