        if (ix + 1 < nx) {
            int covered = hcov[(size_t)ix * hstride + iy] > 0;
            RELAX(u + ny, covered ? 0 : xs[ix + 1] - xs[ix]);
        }
        if (iy > 0) {
            int covered = vcov[(size_t)ix * vstride + iy - 1] > 0;
            RELAX(u - 1, covered ? 0 : ys[iy] - ys[iy - 1]);
        }
        if (iy + 1 < ny) {
            int covered = vcov[(size_t)ix * vstride + iy] > 0;
            RELAX(u + 1, covered ? 0 : ys[iy + 1] - ys[iy]);
        }

#undef RELAX
    }

    printf("%d\n", dist[target]);

    free(rects);
    free(xs);
    free(ys);
    free(hcov);
    free(vcov);
    free(dist);
    free(pos);
    free(heap);
    return 0;
}
